function output = heartlib(M)
% output = heartlib(M)
%
%    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector  from MeshConnectivity
%    
%    M : FaceMesh 
%    
%    V, E, F = ElementSets( M )
%    `∂⁰`, `∂¹` = BoundaryMatrices(M) 
%    `B⁰`, `B¹` = UnsignedBoundaryMatrices(M)
%    `B⁰ᵀ` = `B⁰`ᵀ
%    `B¹ᵀ` = `B¹`ᵀ
%    
%    Vertices(S) = S₁ where S: CellularSet
%    Edges(S)    = S₂ where S: CellularSet 
%    Faces(S)    = S₃ where S: CellularSet
%     
%    Vertices(f) = vertexset(NonZeros(`B⁰` (`B¹` IndicatorVector({f})))) where f ∈ F
%    Vertices(G) = vertexset(NonZeros(`B⁰` (`B¹` IndicatorVector(G)))) where G ⊂ F
%    Vertices(e) = vertexset(NonZeros(`B⁰` IndicatorVector({e}))) where e ∈ E
%    Vertices(H) = vertexset(NonZeros(`B⁰` IndicatorVector(H))) where H ⊂ E
%     
%    Edges(v) = edgeset(NonZeros(`B⁰ᵀ` IndicatorVector({v}))) where v ∈ V
%    Edges(f) = edgeset(NonZeros(`B¹` IndicatorVector({f}))) where f ∈ F
%    
%    Faces(v) = faceset(NonZeros(`B¹ᵀ` (`B⁰ᵀ` IndicatorVector({v})))) where v ∈ V
%    Faces(e) = faceset(NonZeros(`B¹ᵀ` IndicatorVector({e}))) where e ∈ E
    dimv_0 = M.n_vertices();
    dime_0 = M.n_edges();
    dimf_0 = M.n_faces();
    [V, E, F] = M.ElementSets();
    [dee0, dee1] = M.BoundaryMatrices();
    [B0, B1] = M.UnsignedBoundaryMatrices();
    % `B⁰ᵀ` = `B⁰`ᵀ

    B0T = B0';
    % `B¹ᵀ` = `B¹`ᵀ

    B1T = B1';
    function [ret] = Vertices(S)
        ret = S(1);
    end

    function [ret_1] = Edges(S)
        ret_1 = S(2);
    end

    function [ret_2] = Faces(S)
        ret_2 = S(3);
    end

    function [ret_3] = Vertices_0(f)
        assert(numel(f) == 1);
        assert( ismember(f, F) );

        ret_3 = NonZeros(B0 * (B1 * indicator([f], M.n_faces())));
    end

    function [ret_4] = Vertices_1(G)
        ret_4 = NonZeros(B0 * (B1 * indicator(G, M.n_faces())));
    end

    function [ret_5] = Vertices_2(e)
        assert(numel(e) == 1);
        assert( ismember(e, E) );

        ret_5 = NonZeros(B0 * indicator([e], M.n_edges()));
    end

    function [ret_6] = Vertices_3(H)
        ret_6 = NonZeros(B0 * indicator(H, M.n_edges()));
    end

    function [ret_7] = Edges_0(v)
        assert(numel(v) == 1);
        assert( ismember(v, V) );

        ret_7 = NonZeros(B0T * indicator([v], M.n_vertices()));
    end

    function [ret_8] = Edges_1(f)
        assert(numel(f) == 1);
        assert( ismember(f, F) );

        ret_8 = NonZeros(B1 * indicator([f], M.n_faces()));
    end

    function [ret_9] = Faces_0(v)
        assert(numel(v) == 1);
        assert( ismember(v, V) );

        ret_9 = NonZeros(B1T * (B0T * indicator([v], M.n_vertices())));
    end

    function [ret_10] = Faces_1(e)
        assert(numel(e) == 1);
        assert( ismember(e, E) );

        ret_10 = NonZeros(B1T * indicator([e], M.n_edges()));
    end

    output.V = V;
    output.E = E;
    output.F = F;
    output.dee0 = dee0;
    output.dee1 = dee1;
    output.B0 = B0;
    output.B1 = B1;
    output.B0T = B0T;
    output.B1T = B1T;
    output.Vertices = @Vertices;
    output.Edges = @Edges;
    output.Faces = @Faces;
    output.Vertices_0 = @Vertices_0;
    output.Vertices_1 = @Vertices_1;
    output.Vertices_2 = @Vertices_2;
    output.Vertices_3 = @Vertices_3;
    output.Edges_0 = @Edges_0;
    output.Edges_1 = @Edges_1;
    output.Faces_0 = @Faces_0;
    output.Faces_1 = @Faces_1;
    output.M = M;
end
